function validate([nums1, nums2]) {
  if (!Array.isArray(nums1) || !Array.isArray(nums2)) return 'nums1 and nums2 must be arrays.';
  if (nums1.length !== nums2.length) return 'nums1 and nums2 must have the same length.';
  if (nums1.length < 1 || nums1.length > 100000) return 'Each array needs 1 to 100000 values.';
  if ([...nums1, ...nums2].some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each value is a whole number from 1 to 10^9.';
  return null;
}

