function maxNonDecreasingLength(nums1, nums2) {
  let dp1 = 1;
  let dp2 = 1;
  let best = 1;
  for (let i = 1; i < nums1.length; i++) {
    let next1 = 1;
    let next2 = 1;
    if (nums1[i] >= nums1[i - 1]) {
      next1 = Math.max(next1, dp1 + 1);
    }
    if (nums1[i] >= nums2[i - 1]) {
      next1 = Math.max(next1, dp2 + 1);
    }
    if (nums2[i] >= nums1[i - 1]) {
      next2 = Math.max(next2, dp1 + 1);
    }
    if (nums2[i] >= nums2[i - 1]) {
      next2 = Math.max(next2, dp2 + 1);
    }
    dp1 = next1;
    dp2 = next2;
    best = Math.max(best, dp1, dp2);
  }
  return best;
}

