function maxNonDecreasingLength(nums1, nums2) {
  // For every start, extend greedily: keep the smallest value that is not below the previous pick.
  let answer = 0;
  for (let start = 0; start < nums1.length; start++) {
    let previous = -Infinity;
    let length = 0;
    for (let j = start; j < nums1.length; j++) {
      const options = [nums1[j], nums2[j]].filter(v => v >= previous);
      if (options.length === 0) break;
      previous = Math.min(...options);
      length++;
    }
    answer = Math.max(answer, length);
  }
  return answer;
}

