function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const mode = Math.floor(rand() * 3);
  // Wide random values give short runs, a few small values give ties, a noisy upward trend gives long runs.
  const value = i => {
    if (mode === 0) return 1 + Math.floor(rand() * 1000000000);
    if (mode === 1) return 1 + Math.floor(rand() * (size === 'large' ? 20 : 5));
    return Math.max(1, i * 3 + Math.floor(rand() * 10) - 4);
  };
  const nums1 = [], nums2 = [];
  for (let i = 0; i < n; i++) {
    nums1.push(value(i));
    nums2.push(value(i));
  }
  return [nums1, nums2];
}
